28	    /// Initializes a new instance of the <see cref="SqliteVectorStore"/> class.
29	    /// </summary>
30	    /// <param name="connection"><see cref="SqliteConnection"/> that will be used to manage the data in SQLite.</param>
31	    /// <param name="options">Optional configuration options for this class.</param>
32	    public SqliteVectorStore(
33	        DbConnection connection,
34	        SqliteVectorStoreOptions? options = default)
35	    {
36	        Verify.NotNull(connection);
37	
38	        this._connection = connection;
39	        this._options = options ?? new();
40	    }
